532	export interface BuildResult {
533	  suite: string;
534	  /** Target name this result was generated for (e.g. `'vscode'`, `'claude-code'`, or a custom target). */
535	  target: string;
536	  personaYamlPath: string;
537	  outputPath: string;
538	  content: string;
539	  validationResults: ValidationResult[];
540	  written: boolean;
541	}
542	```
