556	### `PersonaMetadata`
557	
558	```ts
559	export interface PersonaMetadata {
560	  name: string;
561	  displayName?: string;
562	  description?: string;
563	  version?: string;
564	  tools?: string[];
565	  [key: string]: unknown;
566	}
567	```
568	
569	### `PersonaBuildPlugin`
570	
571	```ts
572	export interface PersonaBuildPlugin {
573	  name: string;
574	  onSuiteInit?(suite: SuiteConfig, sharedMeta: Record<string, unknown>): void;
575	  /** Suite-level accumulating hook. Called once per suite after partials are loaded. */
576	  onPartials?(
577	    partialsMap: Record<string, string>,
578	    suiteName: string,
579	    suite: SuiteConfig,
580	  ): Record<string, string>;
581	  onBuildContext?(
582	    context: Record<string, unknown>,
583	    persona: PersonaMetadata,
584	    suite: SuiteConfig,
585	    target?: TargetType,
586	  ): Record<string, unknown>;
587	  /** Per-persona accumulating hook. Called after onBuildContext, before rendering. Receives a shallow copy of the suite-level partialsMap (isolated per persona). */
588	  onPersonaPartials?(
589	    partialsMap: Record<string, string>,
590	    persona: PersonaMetadata,
591	    context: Record<string, unknown>,
592	    suite: SuiteConfig,
593	    target?: TargetType,
594	  ): Record<string, string>;
595	  onPostRender?(output: string, persona: PersonaMetadata, target: TargetType): string;
596	  onValidate?(persona: PersonaMetadata, suite: SuiteConfig, target?: TargetType): ValidationResult[];
597	  frontmatterTemplates?: Partial<Record<TargetType, string>>;
598	}
599	```
600

601	### `TargetType`
602	
603	```ts
604	export type TargetType = string;
605	```
606	
607	Resolves to `string` to allow custom targets alongside the three built-in well-known values (`'vscode'`, `'claude-code'`, `'deep-agents'`). Use the exported constants `TARGET_VSCODE`, `TARGET_CLAUDE_CODE`, and `TARGET_DEEP_AGENTS` for type-safe references to the built-in targets.
608	
609	### `TargetDefinition`
610	
611	```ts
612	export interface TargetDefinition {
613	  name: string;
614	  outputDirKey: string;
615	  filenameContextKey?: string;
616	  defaultFrontmatter: string;
617	  contextFlags?: Record<string, unknown>;
618	  defaultEnabled?: boolean;
619	}
620	```
621	
622	Describes a build target. `name` is the unique target identifier (e.g. `'vscode'`). `outputDirKey` maps to the suite's output directory key. `filenameContextKey` names the build-context field holding a custom output filename for this target. `defaultFrontmatter` is the template used when no plugin or `BuildConfig` override is provided. `contextFlags` is a **declarative** map of context injections (e.g. `{ target_vscode: true }`) — consumed by the runtime via registry-driven lookup (`registry.get(target).contextFlags`). Each key-value pair is injected into the build context for the corresponding target, enabling conditional template rendering. When a target is not present in the registry, the engine falls back to injecting a single boolean via string replacement (`target_${name.replace(/-/g, '_')} = true`). `defaultEnabled` controls whether the target is included in the default build when no explicit `targets` array is configured — defaults to `true` when omitted; set to `false` for opt-in targets (e.g. `'deep-agents'`).
623	
624	### `ValidationResult`
625	
626	```ts
627	export interface ValidationResult {
628	  severity: 'error' | 'warning' | 'info';
629	  message: string;
630	}
631	```
